// Patterns from the pinned PyBot memory/when.py.
pattern!(HOW_LONG_ASK, r###"(?i)\bhow\s+long\s+(?:have|has|had|did)\b|\bhow\s+(?:many|much)\s+(?:months?|weeks?|years?|days?)\s+(?:has|have|had)\s+it\s+been\b"###);
