pattern!(A_YEAR_SAID, r###"\b(?:19|20)\d\d\b"###);
pattern!(BEGAN, r###"(?i)\b(?:started|start|began|begin|kicked\s+off|took\s+up|moved|stopped|quit|gave\s+up|joined|arrived|switched|changed|since|ago|for\s+(?:\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s+(?:days?|weeks?|months?|years?)|got\s+(?:married|engaged|together|a\s+dog|a\s+cat|a\s+puppy|a\s+kitten|the\s+keys)|married|adopted|bought|got|last\s+(?:week|fortnight|month|year))\b"###);
pattern!(DAY_PUT_RIGHT, r###"(?i)\b(?:no,?\s+|actually,?\s+|sorry,?\s+)?(?:it\s+was|it's|it is|i\s+meant|i\s+mean|make\s+that)\b[^.,!?]*\b(?<day>january|february|march|april|may|june|july|august|september|october|november|december|(?:19|20)\d\d|last\s+(?:week|month|year)|\d+\s+(?:days?|weeks?|months?|years?)\s+ago)\b"###);
