fancy!(SHORT_DATE, r###"(?i)\b(?:for|in|on|by|until|till|around|from)\s+(?:the\s+)?(?:(?:early|mid|late)\s+)?(?:september|december|february|november|january|october|august|march|april|june|sept|july|jul|oct|apr|feb|mar|sep|dec|may|aug|jun|nov|jan|wednesday|thursday|saturday|weekend|tuesday|monday|sunday|friday|(?:0?[1-9]|[12]\d|3[01])(?:st|nd|rd|th)?(?!\s*(?:k|grand|thousand|hundred|million|billion|quid|pounds?|dollars?|euros?|cents?|percent|%|per\b|a\s+(?:week|month|year|day)))(?:\s+(?:of\s+)?(?:september|december|february|november|january|october|august|march|april|june|sept|july|jul|oct|apr|feb|mar|sep|dec|may|aug|jun|nov|jan))?)\b|\b(?:is|was|it's|its)\s+(?:in\s+|on\s+)?(?:september|december|february|november|january|october|august|march|april|june|sept|july|jul|oct|apr|feb|mar|sep|dec|may|aug|jun|nov|jan)"###);
